class Solution {
  private static final long MOD = 1_000_000_007L;

  public int numDecodings(String s) {
    long prev2 = 1, prev1 = ways1(s.charAt(0));
    for (int i = 1; i < s.length(); i++) {
      long current =
          (ways1(s.charAt(i)) * prev1 + ways2(s.charAt(i - 1), s.charAt(i)) * prev2) % MOD;
      prev2 = prev1;
      prev1 = current;
    }
    return (int) prev1;
  }

  private long ways1(char c) {
    return c == '*' ? 9 : c == '0' ? 0 : 1;
  }

  private long ways2(char a, char b) {
    if (a == '*' && b == '*') return 15;
    if (a == '*') return b <= '6' ? 2 : 1;
    if (b == '*') return a == '1' ? 9 : a == '2' ? 6 : 0;
    int value = (a - '0') * 10 + b - '0';
    return value >= 10 && value <= 26 ? 1 : 0;
  }
}
